import 'package:paypal_sdk/paypal_sdk.dart';

void main() async {
  final client = PayPalClient(
    clientId: 'YOUR_CLIENT_ID',
    secret: 'YOUR_SECRET',
    environment: PayPalEnvironment.sandbox,
  );
  final order = await client.createOrder(
    amount: '10.00',
    currency: 'USD',
  );
  print('Order ID: ${order.id}');
}
